#!/usr/bin/env python3
# LAMWEB 2.99.575 - /colors (LENH TONG anh Logan 31/10 00:48, muc 3): 572 = a row of BRAND buttons under Find (All + each brand of the salon; the chosen one blue;
#   Find looks inside the chosen brand; sticky with Find); 575 = each color in the grid = ONE REAL FINGER painted in that color (like the big hand: right to the
#   cuticle, glossy; glitter/shimmer sparkle). Only the fingers on screen are painted (IntersectionObserver), one picture per color kept -> smooth on iPhone.
#   New files: assets/hands/tay-thumb.jpg + tay-thumb-shade.png (one finger of tay-07, 132x180). Zoom / big hand / Book / Close: unchanged.
# Run: python3 fix575.py <file colors/index.php>        -> check only
#      python3 fix575.py <file colors/index.php> go     -> backup to ~/app/old + patch
import sys, os, shutil, time, hashlib, json
p = sys.argv[1]; go = len(sys.argv) > 2 and sys.argv[2] == 'go'
s = open(p, encoding='utf-8').read()
def sha(t): return hashlib.sha256(t.encode('utf-8')).hexdigest()[:8]
A = json.loads(r'''[["</style>\n</head>", "/* (2.99.575) 572: the brand row under Find (the chosen one blue); 575: each color = a real finger painted in it */\n.bs{padding-top:6px;scrollbar-width:none}.bs::-webkit-scrollbar{display:none}.bs button.on{background:#2563EB;color:#fff;border-color:#2563EB}\n.c img.fz{width:44px;height:60px;border-radius:12px;object-fit:cover;box-shadow:0 1px 3px rgba(0,0,0,.2)}\n</style>\n</head>"], ["  <div class=\"ks\" id=\"ks\" role=\"group\" aria-label=\"Kind\"></div></div></div>", "  <div class=\"ks\" id=\"ks\" role=\"group\" aria-label=\"Kind\"></div><div class=\"ks bs\" id=\"bs\" role=\"group\" aria-label=\"Brand\"></div></div></div>"], ["  let all = [], kind = '';", "  let all = [], kind = '', brand = '*'; // (2.99.575) '*' = every brand"], ["`<i style=\"background:${esc(c.hex || '#ddd')}\"></i>`;", "(c.hex ? `<img class=\"fz\" alt=\"\" width=\"44\" height=\"60\" data-hex=\"${esc(c.hex)}\" data-fin=\"${esc(c.finish || '')}\" style=\"background:${esc(c.hex)}\" src=\"data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7\">` : `<i style=\"background:#ddd\"></i>`); // (2.99.575) a real finger, painted when it shows"], ["    const brands = [...new Set(all.map(c => c.brand || ''))].sort((a, b) => (a === '') - (b === '') || a.localeCompare(b));\n", "    const brands = [...new Set(all.map(c => c.brand || ''))].sort((a, b) => (a === '') - (b === '') || a.localeCompare(b));\n    if (brand !== '*' && !brands.includes(brand)) brand = '*'; // (2.99.575) the brand row: All + each brand of the salon, in the order of the page\n    $('#bs').innerHTML = brands.length > 1 ? ['*', ...brands].map(b => `<button type=\"button\" data-b=\"${esc(b)}\" class=\"${b === brand ? 'on' : ''}\" aria-pressed=\"${b === brand}\">${b === '*' ? T('All', 'Todos') : esc(b || T('Other', 'Otros'))}</button>`).join('') : '';\n"], ["      const hit = (!kind || c.kind === kind) && ", "      const hit = (!kind || c.kind === kind) && (brand === '*' || (c.brand || '') === brand) && "], ["  $('#q').addEventListener('input', filter);\n", "  $('#q').addEventListener('input', filter);\n  /* (2.99.575) 572: tap a brand -> only its colors (Find looks inside it) */\n  $('#bs').addEventListener('click', (e) => { const b = e.target.closest('[data-b]'); if (!b) return; brand = b.dataset.b; $('#bs').querySelectorAll('[data-b]').forEach(x => { x.classList.toggle('on', x === b); x.setAttribute('aria-pressed', String(x === b)); }); filter(); try { b.scrollIntoView({ block: 'nearest', inline: 'center' }); } catch (x) {} const m = $('main'); if (m && window.scrollY > m.offsetTop) window.scrollTo(0, m.offsetTop - 4); });\n  /* (2.99.575) 575: each color in the grid = one real finger (tay-thumb.jpg + tay-thumb-shade.png, the same painting as the big hand of 570:\n     inside the nail = the color x its light + its shine, at the edge the photo's grey taken out). Only the fingers on screen are painted; one picture per color kept. */\n  const TH = { w: 132, h: 180, p: null, done: new Map() };\n  const thLoad = () => TH.p || (TH.p = Promise.all([img('../assets/hands/tay-thumb.jpg?v=575'), img('../assets/hands/tay-thumb-shade.png?v=575')]).then(([a, m]) => {\n    const cv = document.createElement('canvas'); cv.width = TH.w; cv.height = TH.h; const x = cv.getContext('2d', { willReadFrequently: true });\n    x.drawImage(a, 0, 0, TH.w, TH.h); const base = x.getImageData(0, 0, TH.w, TH.h).data; x.clearRect(0, 0, TH.w, TH.h); x.drawImage(m, 0, 0, TH.w, TH.h);\n    return { base, sd: x.getImageData(0, 0, TH.w, TH.h).data, cv, x }; }).catch(() => null));\n  const thPaint = (H, hex, fin) => { const k = hex + '|' + fin; if (TH.done.has(k)) return TH.done.get(k); const col = rgb(hex); if (!col) return '';\n    const out = H.x.createImageData(TH.w, TH.h), d = out.data, bd = H.base, sd = H.sd, spark = fin === 'glitter' || fin === 'shimmer'; let seed = 7;\n    for (let i = 0; i < d.length; i += 4) { d[i] = bd[i]; d[i + 1] = bd[i + 1]; d[i + 2] = bd[i + 2]; d[i + 3] = 255; const a = sd[i + 3] / 255; if (!a) continue;\n      const f = sd[i] / 255, g = sd[i + 1] / 255; let o = [col[0] * f, col[1] * f, col[2] * f]; if (g) o = o.map(v => v + (255 - v) * g);\n      if (spark) { seed = (seed * 1103515245 + 12345) >>> 0; if ((seed >>> 16) % 1000 < (fin === 'glitter' ? 40 : 18)) o = o.map(v => v + (255 - v) * 0.7); }\n      if (a >= 1) { d[i] = o[0]; d[i + 1] = o[1]; d[i + 2] = o[2]; } else { const gy = sd[i + 2]; d[i] += a * (o[0] - gy); d[i + 1] += a * (o[1] - gy); d[i + 2] += a * (o[2] - gy); } }\n    H.x.putImageData(out, 0, 0); const u = H.cv.toDataURL('image/jpeg', 0.88); TH.done.set(k, u); return u; };\n  const thSet = (el) => thLoad().then(H => { if (H) { const u = thPaint(H, el.dataset.hex, el.dataset.fin || ''); if (u) el.src = u; } });\n  const thIO = 'IntersectionObserver' in window ? new IntersectionObserver((es) => es.forEach(e => { if (e.isIntersecting) { thIO.unobserve(e.target); thSet(e.target); } }), { rootMargin: '400px 0px' }) : null;\n  const thScan = () => document.querySelectorAll('#list img.fz:not([data-th])').forEach(el => { el.dataset.th = '1'; if (thIO) thIO.observe(el); else thSet(el); });\n  new MutationObserver(thScan).observe($('#list'), { childList: true, subtree: true });\n"]]''')
n = [s.count(a) for a, _ in A]
print(p, 'sha', sha(s), 'anchors', *n, 'already', 'tay-thumb' in s)
if 'tay-thumb' in s: sys.exit('STOP: already patched - nothing changed')
if n != [1] * len(A): sys.exit('STOP: an anchor is not found exactly once - nothing changed')
t = s
for a, b in A: t = t.replace(a, b)
if not go: print('NEW would be sha', sha(t)); sys.exit('check only - run again with: go')
bk = os.path.expanduser('~/app/old'); os.makedirs(bk, exist_ok=True); st = time.strftime('%m%d%H%M')
shutil.copy2(p, f'{bk}/colors-index.php.pre-575-{st}')
mode = os.stat(p).st_mode; open(p, 'w', encoding='utf-8').write(t); os.chmod(p, mode)
print('NEW sha', sha(t), 'backup', f'{bk}/colors-index.php.pre-575-{st}')
